const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  page.on('console', message => { if (message.type() === 'error') errors.push(message.text()); });
  await page.goto('http://127.0.0.1:3002');
  await page.locator('#start-button').click();
  const expectedScenes = ['The message on the counter', 'A favor with a price tag', 'Lunch, if you can call it that', 'The call from the clinic', 'The envelope under the magnet'];
  for (const scene of expectedScenes) {
    const title = await page.locator('#scene-title').textContent();
    if (title !== scene) throw new Error(`Expected scene ${scene}; got ${title}`);
    await page.locator('#choice-area button').nth(0).click();
    if (await page.locator('#after-choice').isHidden()) throw new Error('Choice response did not appear');
    await page.locator('#continue-button').click();
  }
  if ((await page.locator('#scene-index').textContent()).trim() !== '06') throw new Error('Ending was not reached');
  const ending = await page.locator('#scene-title').textContent();
  await page.locator('#review-button').click();
  const journalEntries = await page.locator('.journal-entry').count();
  if (journalEntries !== 5) throw new Error(`Expected 5 journal entries; got ${journalEntries}`);
  await page.locator('#close-journal').click();
  await page.reload();
  await page.locator('#resume-button').click();
  if ((await page.locator('#scene-title').textContent()) !== ending) throw new Error('Finished save did not resume at ending');
  await page.locator('#restart-button').click();
  if ((await page.locator('#scene-title').textContent()) !== expectedScenes[0]) throw new Error('Restart did not reset to first scene');
  await page.locator('#choice-area button').nth(0).click();
  await page.reload();
  await page.locator('#resume-button').click();
  if (await page.locator('#after-choice').isHidden()) throw new Error('Pending choice was not restored');
  if ((await page.locator('#journal-count').textContent()).trim() !== '1') throw new Error('Journal was not restored after reload');
  await page.evaluate(() => localStorage.setItem('between-stops-save-v1', JSON.stringify({ scene: 0, cash: 0, energy: 0, closeness: 0, history: [], flags: {}, pending: false, finished: false })));
  await page.reload();
  await page.locator('#resume-button').click();
  for (const key of ['cash', 'energy', 'closeness']) {
    if ((await page.locator(`#${key}-value`).textContent()).trim() !== '0') throw new Error(`${key} zero did not restore`);
  }
  await page.setViewportSize({ width: 390, height: 844 });
  await page.screenshot({ path: '/tmp/opencode/between-stops-mobile.png', fullPage: true });
  const mobile = await page.evaluate(() => ({ width: innerWidth, scrollWidth: document.documentElement.scrollWidth, buttonCount: document.querySelectorAll('#choice-area button').length }));
  if (mobile.scrollWidth > mobile.width) throw new Error(`Mobile horizontal overflow: ${JSON.stringify(mobile)}`);
  if (errors.length) throw new Error(`Browser errors: ${errors.join(' | ')}`);
  console.log(JSON.stringify({ ending, journalEntries, pendingResume: 'passed', zeroRestore: 'passed', mobile, errors }, null, 2));
  await browser.close();
})().catch(error => { console.error(error); process.exit(1); });

