const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  await page.goto('http://127.0.0.1:3002');
  await page.locator('#start-button').click();
  for (let route = 0; route < 3; route++) {
    if (route) await page.locator('#restart-button').click();
    for (let scene = 0; scene < 5; scene++) {
      await page.locator('#choice-area button').nth((scene + route) % 3).click();
      await page.locator('#continue-button').click();
    }
    if ((await page.locator('#scene-index').textContent()).trim() !== '06') throw new Error(`Route ${route} failed to end`);
  }
  for (const width of [320, 390, 620, 768, 1280]) {
    await page.setViewportSize({ width, height: 844 });
    const result = await page.evaluate(() => ({ viewport: innerWidth, document: document.documentElement.scrollWidth }));
    if (result.document > result.viewport) throw new Error(`Overflow at ${width}px: ${JSON.stringify(result)}`);
  }
  if (errors.length) throw new Error(errors.join(' | '));
  console.log('Three choice patterns completed all five scenes; no horizontal overflow at 320, 390, 620, 768, or 1280px.');
  await browser.close();
})().catch(error => { console.error(error); process.exit(1); });
